INSERT INTO insurance_feature (product_id, seq, feature_code, feature_name, display_text, value, unit, description) VALUES
(1, 1, 'I01', '예금자보호', '예금자보호 / 1인당 / 최고 1억원', NULL, NULL, '이 보험계약은 예금자보호법에 따라 해약환급금(또는 만기 시 보험금)에 기타지급금을 합한 금액이 1인당 “1억원까지”(본 보험회사의 여타 보호상품과 합산) 보호 됩니다. 이와 별도로 본 보험회사 보호상품의 사고보험금을 합산한 금액이 1인당 “1억원까지” 보호됩니다. 다만，보험계약자 및 보험료납부자가 법인인 보험 계약의 경우에는 보호되지 않습니다.'),
(1, 2, 'I04', '유형', '보장성보험 / 상해，질병 등', NULL, NULL, '이 상품은 만기시 환급금이 총 납입한 보혐료를 초과하지 않습니다.'),
(1, 3, 'I07', '청약철회기간', '청약철회 기간 / 청약후', NULL, NULL, '이 상품은 청약을 한 날부터 30일 이내(보험증권을 받은 날부터 15일 이내)에 청약철회가 가능합니다.'),
(1, 4, 'I28', '보험가격지수', '보험가격지수 / 남성 / 표준형 계약 기준', 87.8, '%', '보험업계 평균가격대비 이 상품의 보험가격 수준(대표계약 기준)을 비교하는 지수로 100% 초과이면 업계 평균보다 가격수준이 높고，100% 미만이면 업계 평균보다 가격수준이 낮습니다.'),
(1, 5, 'I15', '실손형담보', '실손형 담보 / 비례 보상 / 중복가입 부적절', NULL, NULL, '실손의료보험 및 일상생활 배상책임 보험 등 실손보상형 담보의 경우 중복가입시 보험금을 비례분담하여 지급합니다.'),
(1, 6, 'I16', '보험료갱신형상품', '보험료갱신형 / 보험료 변동가능', NULL, NULL, '이 상품은 위험률 변경 등에 따라 갱신시 보험료가 변동될 수 있습니다.'),
(1, 7, 'I17', '무해지환급금', '해지환급금 / 납입기간 중 해지시', NULL, NULL, '이 상품은 중도해지시 환급금이 없습니다.'),
(2, 1, 'I01', '예금자보호', '예금자보호 / 1인당 / 최고 1억원', NULL, NULL, '이 보험계약은 예금자보호법에 따라 해약환급금(또는 만기 시 보험금)에 기타지급금을 합한 금액이 1인당 “1억원까지”(본 보험회사의 여타 보호상품과 합산) 보호 됩니다. 이와 별도로 본 보험회사 보호상품의 사고보험금을 합산한 금액이 1인당 “1억원까지” 보호됩니다. 다만，보험계약자 및 보험료납부자가 법인인 보험 계약의 경우에는 보호되지 않습니다.'),
