INSERT INTO insurance_coverage (product_id, seq, coverage_name, pay_reason, coverage_amount) VALUES
(17, 1, '일반암진단', '피보험자가 보험기간 중 암보장개시일 이후에 ''일반암(중증갑상선암 포함)''으로 진단 확정되었을 경우(다만, ''고액암''/''일반암''/''여성유방암 또는 전립선암'' 합산 최초 1회한, 2년미만 50% 지급)', '1000만원'),
(17, 2, '여성유방암 또는 전립선암', '피보험자가 보험기간 중 암보장개시일 이후에 ''여성유방암 또는 전립선암''으로 진단 확정되었을 경우(다만, ''고액암''/''일반암''/''여성유방암 또는 전립선암'' 합산 최초 1회한, 2년미만 50% 지급, 여성유방암 180일이내 100만원)', '200만원'),
(17, 3, '갑상선암(중증 갑상선암 제외)', '피보험자가 보험기간 중 갑상선암(중증갑상선암 제외)으로 진단 확정되었을 경우 (다만, 최초 1회 한, 2년미만 50% 지급)', '100만원'),
(17, 4, '소액암', '피보험자가 보험기간 중 기타피부암, 대장점막내암, 비침습방광암, 제자리암 또는 경계성종양으로 진단 확정되었을 경우 (다만, 각각 최초 1회 한, 2년미만 50% 지급)', '100만원'),
(18, 1, '일반암진단급여금', '보험기간 중 암보장개시일 이후에 피보험자가 “일반암”으로 진단확정된 경우 (다만, 최초 1회의 진단확정에 한하여 지급)', '1000만원'),
(18, 2, '특정암진단급여금', '보험기간 중 암보장개시일 이후에 피보험자가 “특정암”으로 진단확정된 경우 (다만, 최초 1회의 진단확정에 한하여 지급)', '200만원'),
(18, 3, '기타피부암진단급여금', '보험기간 중 피보험자가 “기타피부암”으로 진단확정된 경우 (다만, 최초 1회의 진단확정에 한하여 지급)', '100만원'),
(18, 4, '갑상선암진단급여금', '보험기간 중 피보험자가 “갑상선암”으로 진단확정된 경우 (다만, 최초 1회의 진단확정에 한하여 지급)', '100만원'),
(18, 5, '제자리암진단급여금', '보험기간 중 피보험자가 “제자리암”으로 진단확정된 경우 (다만, 최초 1회의 진단확정에 한하여 지급)', '100만원'),
(19, 1, '암 진단자금', '보험기간 중 피보험자가 암 보장개시일 이후에 “암”(기타피부암, 특정갑상선암 및 대장점막내암, 경계성종양, 제자리암 제외)으로 진단확정 되었을 때(최초 1회한, 1년미만 50%, 단 유방암의 경우 180일 경과이전 진단시 20%, 180일 초과 1년 미만 50% 지급)', '1000만원'),
(19, 2, '소액암 진단자금', '보험기간 중 피보험자가 기타피부암, 제자리암, 대장점막내암, 경계성종양, 특정갑상선암으로 진단이 확정되었을 때(각 최초 1회한, 1년미만 50%)', '200만원'),
(19, 3, '특정3대암 진단자금', '보험기간 중 피보험자가 암 보장개시일 이후에 특정3대암으로 진단이 확정되었을 때(최초 1회한, 1년미만 50%)', '1000만원'),
(20, 1, '암진단비(유사암제외)', '암 보장개시일 이후에 「암」으로 진단 확정된 경우 최초 1회에 한하여 이 보장의 보험가입금액을 암진단비(유사암제외)로 지급(1년미만 50%지급)', '1000만원'),
(21, 1, '일반암', '보험기간 중 피보험자가 암보장개시일 이후에 암으로 진단이 확정되었을 때(특정3대암, 유방암 또는 남녀생식기관련암 이외의 암, 최초 1회한, 가입 후 2년 미만 50% 지급)', '1000만원'),
(21, 2, '특정3대암', '보험기간 중 피보험자가 암보장개시일 이후에 특정3대암으로 진단이 확정되었을 때(최초 1회한, 가입 후 2년 미만 50% 지급)', '2000만원'),
(21, 3, '유방암 및 남녀생식기암', '보험기간 중 피보험자가 암보장개시일 이후에 암으로 진단이 확정되었을 때(유방암 또는 남녀생식기 관련암, 최초 1회한, 가입 후 2년 미만 50% 지급)', '200만원'),
(21, 4, '소액암', '보험기간 중 피보험자가 암보장개시일 이후에 암으로 진단이 확정되었을 때(기타피부암, 특정갑상선암, 대장점막암, 비침습방광암, 제자리암, 경계성종양 시, 최초 1회한, 가입 후 2년 미만 50% 지급)', '100만원'),
(22, 1, '암(유방암/전립선암제외)치료급여금', '암보장개시일 이후 암(유방암/전립선암제외)진단시(최초1회한)', '1000만원'),
