(51, 40, '심혈관질환(특정Ⅰ,I49제외)진단', '‘심혈관질환(특정Ⅰ, I49제외)’으로 진단확정된 경우 특약가입금액 (최초 1회한) 지급 ‘신생아특정심혈관질환’으로 진단확정된 경우 특약가입금액의 20% (최초 1회한) 지급', '1,000만원'),
(51, 41, '심혈관질환(특정Ⅱ)진단', '심혈관질환(특정Ⅱ)*으로 진단 확정된 경우 가입금액 지급 (최초 1회한) ※ 급성심근경색증, 후속심근경색증, 인공소생에 성공한 심장정지 등', '1,000만원'),
(51, 42, '심혈관질환(특정2대)진단', '심혈관질환(특정2대)으로 진단 확정된 경우 특약가입금액 (최초 1회한) 지급 ‘신생아심장리듬장애’로 진단확정된 경우 특약가입금액의 20% (최초 1회한) 지급', '500만원'),
(51, 43, '심혈관질환(대동맥판막협착증)진단', '심혈관질환(대동맥판막협착증)으로 진단 확정된 경우 가입금액 지급(최초 1회한)', '100만원'),
(51, 44, '심혈관질환(심근병증)진단', '심혈관질환(심근병증)으로 진단 확정된 경우 가입금액 지급(최초 1회한)', '1,000만원'),
(51, 45, '어린이개흉심장수술', '심장병으로 인하여 개흉심장수술을 받은 경우 가입금액 지급(최초1회한)', '300만원'),
(51, 46, '어린이심장시술', '심장시술을 받은 경우 가입금액 지급(최초1회한)', '200만원'),
(51, 47, '양성뇌종양진단', '양성뇌종양으로 진단 확정된 경우 가입금액 지급(최초 1회한)', '3,000만원'),
(51, 48, '뇌혈관질환(Ⅰ)진단', '뇌혈관질환(Ⅰ)*으로 진단 확정된 경우 가입금액 지급 (최초 1회한) ※ 출혈 또는 경색증으로 명시되지 않은 뇌졸중, 기타 뇌혈관질환, 달리 분류된 질환에서의 뇌혈관 장애, 뇌혈관질환의 후유증', '1,000만원'),
(51, 49, '뇌혈관질환(Ⅱ)진단', '뇌혈관질환(Ⅱ)*으로 진단 확정된 경우 가입금액 지급 (최초 1회한) ※ 거미막하출혈, 뇌내출혈, 뇌경색증 등 신생아뇌출혈로 진단 확정된 경우 가입금액의 20% 지급(최초 1회한)', '1,000만원'),
(51, 50, '모야모야병개두수술', '모야모야병의 치료를 직접적인 목적으로 개두수술을 받은 경우 수술 1회당 가입금액 지급', '100만원'),
(51, 51, '심뇌혈관질환수술', '심뇌혈관질환으로 수술을 받은 경우 수술 1회당 가입금액 지급', '800만원'),
(51, 52, '중증세균성수막염진단', '중증 세균성 수막염으로 진단 확정된 경우 가입금액 지급(최초1회한)', '3,000만원'),
(51, 53, '수족구진단(연간1회한)', '수족구로 진단확정된 경우 가입금액 지급(연간1회한)', '10만원'),
(51, 54, '중대한재생불량성빈혈진단', '중대한 재생불량성 빈혈로 진단 확정된 경우 가입금액 지급(최초 1회한)', '1,000만원'),
(51, 55, '기흉진단', '기흉으로 진단확정된 경우 가입금액 지급(최초 1회한) 신생아기흉으로 진단확정된 경우 가입금액의 20% 지급(최초 1회한)', '100만원'),
(51, 56, '수두진단', '수두로 진단확정된 경우 가입금액 지급(최초1회한)', '30만원'),
(51, 57, '특정감염병진단(갱신형)', '중증 세균성 수막염으로 진단 확정된 경우 가입금액 지급(최초1회한)', '10만원'),
(51, 58, '독감(인플루엔자)입원일당(1-30일)', '독감(인플루엔자)의 치료를 직접적인 목적으로 1일이상 입원하여 치료를 받은 경우 입원 1일당 가입금액 지급(30일한도)', '3만원'),
(51, 59, '독감(인플루엔자)항바이러스제치료(연간1회한)(갱신형)', '독감(인플루엔자)''으로 ''독감 항바이러스제''를 처방받은 경우 가입금액 지급(연간 1회한)', '20만원'),
(51, 60, '골절진단', '상해의 직접결과로써 골절로 진단확정된 경우 1사고당 가입금액 지급', '30만원'),
(51, 61, '깁스치료', '상해 또는 질병으로 깁스치료를 받은 경우 1사고당 또는 하나의 질병당 가입금액 지급(부목치료 제외)', '40만원'),
(51, 62, '골절(치아파절제외)부목치료', '상해로 골절(치아파절제외) 진단 확정되고 부목치료를 받은 경우 가입금액 지급', '5만원'),
(51, 63, '골절수술Ⅱ', '상해의 직접결과로써 골절로 진단확정되고, 그 치료를 직접적인 목적으로 수술을 받은 경우 1사고당 가입금액 지급', '100만원'),
(51, 64, '5대골절진단', '상해의 직접결과로써 5대골절(머리의 으깸손상, 목/흉추/요추/골반/대퇴골 골절, 흉추의 다발골절)로 진단 확정된 경우 가입금액 지급', '50만원'),
(51, 65, '화상진단', '심재성 2도 이상의 화상으로 진단확정된 경우 가입금액 지급', '50만원');
INSERT INTO insurance_coverage (product_id, seq, coverage_name, pay_reason, coverage_amount) VALUES
(51, 66, '중증화상/부식진단', '상해로 신체표면적 20%이상의 3도화상 또는 부식으로 진단확정된 경우 가입금액 지급(최초1회한)', '3,000만원'),
(51, 67, '화상수술Ⅱ', '심재성 2도 이상의 화상으로 진단확정되고, 그 치료를 직접적인 목적으로 수술을 받은 경우 1사고당 가입금액 지급', '50만원'),
(51, 68, '상해흉터성형수술Ⅱ', '상해로 ''상해흉터성형수술''※을 받은 경우 아래금액 지급 - 안면부: 수술 1cm당 30만원 - 상지,하지: 수술 1cm당 15만원 (단, 3cm이상에 한함) ※ 최고 1,800만원 한도 ※ 안면부, 상지, 하지에 외형상의 반흔(흉터)이나 추상장해, 신체의 기형이나 기능장해가 발생하여 그 원상회복을 목적으로 사고일로부터 2년이내 받은 성형수술', '15만원'),
(51, 69, '자동차사고(스쿨존내교통사고)', '스쿨존내 교통사고로 인한 상해를 입은 경우 가입금액 지급', '50만원'),
(51, 70, '뇌·내장손상수술', '상해로 뇌손상 또는 내장손상을 입고 사고일부터 180일 이내에 개두/개흉/개복수술을 받은 경우 가입금액 지급(최초 1회한)', '500만원'),
(51, 71, '부정교합치료', 'Angle씨 부정교합(不正咬合) 분류법의 Ⅱ급 또는 Ⅲ급으로 치과의사의 판정을 받고 그로 인하여 교정치료가 필요하다는 치과의사의 진단(단, 단순치열교정은 제외)시 가입금액 지급(최초 1회한) ※ 보장개시일은 피보험자의 보험나이 6세 계약해당일이며, 해당보험료를 추가 납부하여야 함', '200만원'),
(51, 72, '성조숙증진단', '성조숙증으로 진단확정된 경우 가입금액 지급(최초 1회한) ※ 보험나이 5세 이전 가입자의 경우,보장개시일은 피보험자의 보험나이 5세 계약해당일이며, 해당보험료를 추가 납부하여야 함', '10만원'),
(51, 73, '의료사고법률비용', '의료법 제3조에서 정한 의료기관에서 의사의 진단에 따른 치료 중 또는 그 치료의 직접결과로 의료사고가 발생하여 소를 제기한 경우 변호사 착수금의 80%해당액으로 1사고당 가입금액 한도 지급(단, 1심에 한함)', '200만원'),
(51, 74, '일상생활중배상책임Ⅳ(가족)(누수사고포함)(대인)(갱신형)', '피보험자 본인 및 가족이 일상생활중 타인의 신체에 장해 또는 재물에 손해를 입힘으로써 법률상의 배상책임을 부담하는 경우 대인사고로 구분하여 각각 보험증권에 기재된 금액 한도 보상', '1억원'),
(51, 75, '일상생활중배상책임Ⅳ(가족)(누수사고포함)(대물,누수)(갱신형)', '피보험자 본인 및 가족이 일상생활중 타인의 신체에 장해 또는 재물에 손해를 입힘으로써 법률상의 배상책임을 부담하는 경우 대물(누수)사고로 구분하여 각각 보험증권에 기재된 금액 한도 보상 (자기부담금 : 대물(누수)사고로 구분하여 보험증권에 기재된 금액)', '1억원'),
(51, 76, '일상생활중배상책임Ⅳ(가족)(누수사고포함)(대물,누수외)(갱신형)', '피보험자 본인 및 가족이 일상생활중 타인의 신체에 장해 또는 재물에 손해를 입힘으로써 법률상의 배상책임을 부담하는 경우 대물(누수이외)사고로 구분하여 각각 보험증권에 기재된 금액 한도 보상 (자기부담금 : 대물(누수이외)사고로 구분하여 보험증권에 기재된 금액)', '1억원'),
(52, 1, '스쿨존교통사고치료자금', '보험기간 중 피보험자에게 “스쿨존 교통사고”가 발생하고, 그 “스쿨존 교통사고”를 직접적인 원인으로 보험기간 중 치료를 받았을 때', '[사고1회당] 50만원'),
(52, 2, '교통재해장해급여금', '보험기간 중 피보험자가 “교통재해”로 인하여 보험기간 중 장해분류표에서 정한 장해지급률 중 3%이상 100%이하에 해당하는 장해상태가 되었을 때', '3000만원 x 해당 장해지급률'),
(53, 1, '상해입원일당', '해의 직접결과로 생활기능 또는 업무능력에 지장을 가져와 병원 또는 의원에서 입원하여 치료를 받은 경우 입원 1일당 보험가입금액을 지급', '1.4만원'),
(53, 2, '외상후스트레스장애(PTSD) 진단보장', '급격하고 우연한 외래의 사고(외상)가 발생하여 해당 외상을 원인으로 외상 발생일로부터 1년 이내에 ''외상후스트레스장애''로 진단확정된 경우, 연간 1회에 한하여 지급', '10만원'),
(53, 3, '골절수술비', '상해의 직접결과로써 ''골절분류표''에서 정한 골절을 입고 치료를 직접적인 목적으로 수술을 받을 때, 수술 1회당 지급', '10만원'),
(53, 4, '골절진단비(치아파절 제외)', '상해의 직접결과로써 ''골절분류표''에서 정한 골절로 진단확정시 지급', '10만원'),
(53, 5, '화상수술비', '급각하고도 우연한 외래의 사고로 인하여 신체에 상해를 입어 ''화상분류표에''서 정한 화상을 입고 그 치료를 직접적인 목적으로 병원 또는 의원 등에서 수술을 받는 때 수술 1회당 지급', '10만원'),
(53, 6, '화상진단비', '급각하고도 우연한 외래의 사고로 인하여 신체에 상해를 입어 ''화상분류표에''서 정한 화상으로 진단확정된 경우 지급', '19.8만원'),
(53, 7, '상해흉터복원수술비', '상해로 병원 또는 의원등에서 치료를 받고 그 직접적인 결과로 인하여 안면부,상지,하지에 외형상의 반흔이나 추상장해, 신체의 기형이나 기능장해가 발생하여 그 원상회복을 목적으로 상해발생일로부터 2년 이내에 성형수술을 받은 경우 지급', '7만원'),
(54, 1, '어린이질환 수술보험금', '피보험자가 보험기간 중 어린이중요질환 또는 어린이생활질환의 직접적인 치료를 목적으로 수술을 받았을 때', '어린이중요질환 : 100만원 어린이생활질환 : 25만원 (수술 1회당)'),
(54, 2, '화상수술보험금', '피보험자가 보험기간 중 화상의 직접적인 치료를 목적으로 수술을 받았을 때', '25만원(수술 1회당)'),
(54, 3, '주요법정 감염병 치료비', '피보험자가 보험기간 중 주요법정감염병으로 해당 보건소에 신고되어 감염병환자로 진단 확정되었을 때', '25만원(발생 1회당)'),
(55, 1, '응급실내원진료비(응급)', '응급환자로서 응급실애 내원하여 진료를 받은 경우', '5만원'),
(55, 2, '폐렴진단비(연간1회한)', '폐렴으로 진단 확정된 경우(연간 1회한)', '20만원'),
